import {statementText,label,topic,words,targetText,sourceRefs,missingText} from '../../integrations/javascript/evidence-model.mjs';
export const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const list=items=>`<ul>${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
export const translationNotes=s=>(s.translation_notes||[]).length?`<p class="muted"><strong>Translation notes:</strong> ${s.translation_notes.map(esc).join('; ')}</p>`:'';
export const extractionNotes=p=>(p.extraction?.notes||[]).length?`<section class="scope-notes"><h2>Extraction notes</h2>${list(p.extraction.notes)}</section>`:'';
export const sourceCoverage=p=>(p.source_coverage||[]).length?`<details class="scope-details"><summary>Source coverage${p.source_coverage.some(d=>d.status!=='complete')?' · Some content could not be recovered':''}</summary><p>Recovery runs automatically. Missing content is never treated as evidence that a policy does not exist.</p>${p.source_coverage.map(d=>`<article><strong>${esc(d.title)}</strong> · ${esc(d.status)} · ${d.pages} pages${list(d.issues.map(i=>typeof i==='string'?i:`Page ${i.page}: ${i.notes.join('; ')}`))}</article>`).join('')}</details>`:'';
export const publicationControl=p=>p.id&&!p.presentation_fixture?`<details class="moderation"><summary>${p.published===false?'Unpublished':'Published automatically'} · optional moderation</summary><button data-publication="${esc(p.id)}" data-published="${p.published===false?'true':'false'}">${p.published===false?'Publish result':'Unpublish result'}</button><p>Saved versions and evidence stay available in history.</p></details>`:'';
const pairs=items=>`<dl class="readable-fields">${items.filter(([,v])=>v!==null&&v!==undefined&&v!==''&&(!Array.isArray(v)||v.length)).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(Array.isArray(v)?v.length?v.join('; '):'No extracted value':v??'No extracted value')}</dd></div>`).join('')}</dl>`;
export const sourceLine=(p,r)=>sourceRefs(p,r).map(s=>`${s.title} · ${s.pages.length===1?'page':'pages'} ${s.pages.join(', ')}`).join('; ');
export function originalPage(p,d,page){
 if(p.presentation_fixture||!p.id||!d.document_id||!d.path?.toLowerCase().endsWith('.pdf')||!Number.isInteger(page)||page<1||page>d.pages)return '';
 return `<p><a href="/api/ai/documents/${encodeURIComponent(p.id)}/${encodeURIComponent(d.document_id)}?inline=1#page=${page}" target="_blank" rel="noopener">Open original PDF · physical page ${page}</a></p>`;
}
export function preparationNotes(d,page){
 const check=d.page_checks?.find(item=>item.page===page),automatic=check?.automatic,review=check?.review;
 const method=automatic?.method||(review?'existing_review':null);
 const name=method==='existing_review'?(review?.method==='ocr'?'Human-reviewed OCR transcription':'Human-reviewed transcription'):({native:'Native PDF text',alternate_parser:'Alternate PDF text extraction',vision:'AI image transcription',ocr:'Local OCR transcription',native_partial:'Partial native PDF text'}[method]||'Text preparation method not recorded');
 const notes=automatic?.notes||(review?.note?[review.note]:[]);
 return `<p class="muted"><strong>Source text:</strong> ${esc(name)}${automatic?.status?` · Page coverage: ${esc(automatic.status)}`:''}. ${['vision','ocr','native_partial'].includes(method)?'Check the original PDF for scan, table and layout details.':''}</p>${notes.length?`<details><summary>Page preparation notes</summary>${list(notes)}</details>`:''}`;
}
export function evidenceReader(p,ids,{originalLinks=true}={}){
  const ev=new Map(p.extraction.evidence.map(e=>[e.local_id,e]));
  const segments=new Map(p.sources.flatMap(d=>d.segments.map(s=>[s.id,{...s,document:d.title,source:d}])));
  const selected=new Set();const include=id=>{if(selected.has(id))return;selected.add(id);ev.get(id)?.context_evidence_ids?.forEach(include);};ids.forEach(include);
  if(!selected.size)return '<p>No citation supplied. This is not a verified source claim.</p>';
  return [...selected].map(id=>{const e=ev.get(id),s=e&&segments.get(e.segment_id);if(!s)return `<p class="callout">Evidence unavailable: ${esc(id)}. No substitute passage is shown.</p>`;
    return `<section class="passage"><h3>${esc(s.document)} · page ${esc(s.page)}</h3>${originalLinks?originalPage(p,s.source,s.page):''}${preparationNotes(s.source,s.page)}<p class="muted">${ids.includes(id)?'Cited passage':'Linked context'} · ${esc(id)}</p><div class="bilingual"><section><h4>Original quotation (${esc(s.language)})</h4><p class="source-text" lang="${esc(s.language)}" dir="auto">${esc(e.quote_original)}</p></section><section><h4>English segment · ${esc(words(s.translation_method))}</h4><p class="source-text" lang="en">${esc(s.english_text)}</p></section></div>${translationNotes(s)}<p class="muted">English is the stored full segment and may extend beyond the original quotation.</p></section>`;
  }).join('');
}
function linkedTo(r,item){return item.target_ids?.length?`Applies to: ${item.target_ids.map(id=>r.targets.find(t=>t.local_id===id)?.metric_text||id).join('; ')}`:'Applies to this record generally; no individual target specified.';}
export function recordDetails(p,r,{originalLinks=true}={}){
 const reader=ids=>evidenceReader(p,ids,{originalLinks});
 const targets=r.targets.map((t,i)=>`<section class="detail-section"><h3>${esc(targetText(t))}</h3><p>${esc(label(p,'conditionalities',t.conditionality))}${t.condition_text?` · Condition: ${esc(t.condition_text)}`:''}</p>${pairs([['Target type',label(p,'target_kinds',t.target_kind)],['Baseline',t.baseline_value?.raw_token??missingText(p,r,`/targets/${i}/baseline_value`)],['Baseline period',t.baseline_period??missingText(p,r,`/targets/${i}/baseline_period`)],['Basis',label(p,'target_bases',t.basis)],['Denominator',t.denominator],['Scenario',t.scenario],['Total or additional',label(p,'target_totals',t.total_or_additional)],['Sector scope',t.sector_scope],['Gas scope',t.gas_scope],['Land-use accounting',t.lulucf_treatment],['GWP basis',t.gwp_basis]])}<details><summary>Target evidence</summary>${reader(t.evidence_ids)}</details></section>`).join('');
 const actors=r.actors.map(a=>`<article><h4>${esc(a.name_en)} · ${esc(label(p,'actor_roles',a.role))}</h4><p>${esc(a.name_original)}<br>${esc(linkedTo(r,a))}</p><details><summary>Responsibility evidence</summary>${reader(a.evidence_ids)}</details></article>`).join('');
 const finance=r.finance.map(f=>`<article><h4>${esc(label(p,'finance_kinds',f.kind))}</h4>${pairs([['Statement',f.description_en],['Amount',f.amount?.raw_token],['Currency',f.currency],['Price period',f.price_period],['Implementation period',f.implementation_period]])}<p>${esc(linkedTo(r,f))}</p><details><summary>Finance evidence</summary>${reader(f.evidence_ids)}</details></article>`).join('');
 const risks=r.risk_contexts.map(c=>`<article>${pairs([['Source hazard wording',c.hazard_text],['Exposed assets or places',c.exposed_assets_or_places],['Vulnerability drivers',c.vulnerability_drivers],['Stated capacities',c.stated_capacities],['Consequence',c.consequence_en],['Likelihood wording',c.likelihood_text],['Severity wording',c.severity_text],['Assessment period',c.assessment_period],['Scenario',c.scenario],['Action connection',label(p,'risk_action_links',c.action_link)],['Connection basis',words(c.link_basis)]])}<p>${esc(linkedTo(r,c))}</p><details><summary>Risk evidence</summary>${reader(c.evidence_ids)}</details></article>`).join('');
 const indicators=r.indicators.map(i=>`<article><h4>${esc(i.name_en)}</h4>${pairs([['Unit',i.unit_raw],['Baseline',i.baseline_value?.raw_token],['Baseline period',i.baseline_period],['Cadence',i.cadence],['Data source',i.data_source]])}<p>${esc(linkedTo(r,i))}</p><details><summary>Indicator evidence</summary>${reader(i.evidence_ids)}</details></article>`).join('');
 const details=r.details.map(d=>`<article><h4>${esc(label(p,'detail_kinds',d.kind))}</h4><p>${esc(d.text_en)}</p><p class="muted">${esc(linkedTo(r,d))}</p><details><summary>Supporting evidence</summary>${reader(d.evidence_ids)}</details></article>`).join('');
 const definitions=r.labels.topic_ids.map(id=>{const t=topic(p,id);return `<li><strong>${esc(t?.name||id)}</strong> · ${esc(id)}<p>${esc(t?.definition||'Archived definition unavailable.')}</p><p class="muted">${esc(t?.routing_rule||'')}</p></li>`;}).join('');
 const facets=Object.entries(r.labels).filter(([k,v])=>!['topic_ids','unmapped_terms'].includes(k)&&v.length).map(([k,ids])=>`<h4>${esc(p.validation_codebook?.dimensions?.find(d=>d.id===k)?.label||words(k))}</h4><ul>${ids.map(id=>`<li>${esc(label(p,k,id))} — ${esc(p.validation_codebook?.dimensions?.find(d=>d.id===k)?.options.find(o=>o.id===id)?.definition||'Definition unavailable')}</li>`).join('')}</ul>`).join('');
 const support=r.field_support.map(s=>`<article><h4>${esc(words(s.field_path.replaceAll('/',' · ')))} · ${esc(words(s.basis))}</h4><p>${esc(s.reason)}</p><details><summary>Classification or field evidence</summary>${reader(s.evidence_ids)}</details></article>`).join('');
 return `<p class="record-meta">${esc(statementText(p,r))}</p><p class="brief-lead">${esc(r.description_en)}</p><p class="muted">${esc(sourceLine(p,r))}</p>${pairs([['Reporting party',r.geography.reporting_party],['Geographic scope',label(p,'geography_scopes',r.geography.scope)],['Countries',r.geography.country_codes],['Places',r.geography.locations],['Reference period',r.reference_period]])}
 <h3>Original and English evidence</h3>${reader(r.evidence_ids)}
 <details class="detail-section"><summary>Targets, baseline, scope and target meaning (${r.targets.length})</summary>${targets||'<p>Qualitative record; no structured target extracted.</p>'}</details>
 <details class="detail-section"><summary>Responsibilities, finance and monitoring</summary><h3>Responsibilities</h3>${actors||`<p>${esc(missingText(p,r,'/actors'))}</p>`}<h3>Finance and support</h3>${finance||`<p>${esc(missingText(p,r,'/finance'))}</p>`}<h3>Indicators</h3>${indicators||`<p>${esc(missingText(p,r,'/indicators'))}</p>`}${details}</details>
 <details class="detail-section"><summary>Risk context and action connections</summary>${risks||'<p>No structured risk context extracted.</p>'}</details>
 <details class="detail-section"><summary>Why these labels?</summary><p>${p.validation_codebook?'Definitions come from this profile’s archived validation codebook':'No archived codebook is included in this result; original label identifiers are retained'}${p.presentation_fixture?' (synthetic fixture snapshot)':''}. Labels are classifications; definitions alone are not evidence.</p><ul>${definitions}</ul>${facets}${r.labels.unmapped_terms.length?`<h4>Unmapped terms</h4>${r.labels.unmapped_terms.map(t=>pairs(Object.entries(t))).join('')}`:''}<h4>Recorded field support</h4>${support}</details>
 <details class="detail-section"><summary>Evidence gaps and qualifications</summary>${r.missing_fields.length?pairs(r.missing_fields.map(m=>[words(m.field_path.replaceAll('/',' · ')),`${label(p,'missing_reasons',m.reason)}${m.detail?': '+m.detail:''}`])):'<p>No material field gap recorded. Empty fields do not establish source or national absence.</p>'}${list(r.quality_flags)}</details>`;
}
export function openReader(title,body){
 let dialog=document.getElementById('report-reader');
 if(!dialog){dialog=document.createElement('dialog');dialog.id='report-reader';dialog.className='evidence-panel';dialog.setAttribute('aria-labelledby','reader-title');document.body.append(dialog);}
 const focus=document.activeElement,scroll=window.scrollY;
 dialog.innerHTML=`<div class="dialog-head"><div><div class="eyebrow">VERIFY THE EVIDENCE</div><h2 id="reader-title">${esc(title)}</h2></div><button aria-label="Close evidence" autofocus>×</button></div><div class="dialog-body">${body}</div>`;
 dialog.querySelector('button').onclick=()=>dialog.close();
 dialog.onclose=()=>{focus?.focus({preventScroll:true});window.scrollTo(0,scroll);};
 dialog.showModal();dialog.scrollTop=0;
}
